class ToyReweight:
    """Custom per-event MC weight with symmetric variations."""

    name = "toy_reweight"
    has_variations = True

    @staticmethod
    def weight(events):
        # Nominal weight: LHEWeight_originalXWGTUP normalized to 1
        nominal = events.LHEWeight_originalXWGTUP / events.LHEWeight_originalXWGTUP.mean()

        return {
            "nominal": nominal,
            "up": nominal * 1.05,
            "down": nominal * 0.95,
        }
